71	  reserve(task: string, usd: number): Reservation {
72	    checkAmount(usd, "reserve amount");
73	    const runTotal = this.#used + this.#reserved + usd;
74	    if (runTotal > this.runCapUsd) {
75	      throw new BudgetExceeded(
76	        "run",
77	        usd,
78	        `run budget exceeded: $${this.#used.toFixed(4)} used + $${this.#reserved.toFixed(4)} reserved + $${usd.toFixed(4)} requested > $${this.runCapUsd.toFixed(4)} cap`,
79	      );
80	    }
81	    const taskTotal = (this.#taskUsed.get(task) ?? 0) + (this.#taskReserved.get(task) ?? 0);
82	    if (taskTotal + usd > this.taskCapUsd) {
83	      throw new BudgetExceeded(
84	        "task",
85	        usd,
86	        `task ${task} budget exceeded: $${taskTotal.toFixed(4)} against the task + $${usd.toFixed(4)} requested > $${this.taskCapUsd.toFixed(4)} cap`,
87	      );
88	    }
89	
90	    this.#reserved += usd;
91	    this.#taskReserved.set(task, (this.#taskReserved.get(task) ?? 0) + usd);
92	
93	    let state: "open" | "committed" | "released" = "open";
94	    const end = (kind: "committed" | "released"): void => {
95	      if (state !== "open") throw new Error(`reservation for ${task} was already ${state}`);
96	      state = kind;
97	    };
98	
99	    return {
100	      commit: (actualUsd: number): void => {
101	        checkAmount(actualUsd, "commit amount");
102	        end("committed");
103	        this.#reserved -= usd;
104	        this.#used += actualUsd;
105	        this.#taskReserved.set(task, (this.#taskReserved.get(task) ?? 0) - usd);
106	        this.#taskUsed.set(task, (this.#taskUsed.get(task) ?? 0) + actualUsd);
107	      },
108	      release: (): void => {
109	        end("released");
110	        this.#reserved -= usd;
111	        this.#taskReserved.set(task, (this.#taskReserved.get(task) ?? 0) - usd);
112	      },
113	    };
114	  }
115	
116	  /** Amount committed so far. Open reservations are not counted here. */
117	  used(): number {
118	    return this.#used;
119	  }
120	
121	  /** Run cap minus committed spend minus open reservations. Over-spend (a commit above the cap) makes it negative. */
122	  remaining(): number {
123	    return this.runCapUsd - this.#used - this.#reserved;
124	  }
